set -e; D="$TMPDIR/rupert-test"; mkdir -p "$D"; cat > "$D/instr.html" <<'EOF'
<script>
(function () {
  var q = new URLSearchParams(location.search);
  var T = q.has('t') ? parseFloat(q.get('t')) : null;
  var overlay = null;
  function log(msg) {
    if (!overlay) {
      overlay = document.createElement('pre');
      overlay.id = '__dbg';
      overlay.style.cssText = 'position:fixed;left:0;top:0;max-width:98vw;max-height:70vh;overflow:auto;margin:0;padding:6px;background:rgba(255,255,255,0.95);color:#b00;font:12px/1.3 monospace;z-index:9999;white-space:pre-wrap';
      document.documentElement.appendChild(overlay);
    }
    overlay.textContent += msg + '\n';
  }
  window.__log = log;
  window.addEventListener('error', function (e) { log('ERROR: ' + e.message + ' @' + e.lineno); });
  var ce = console.error;
  console.error = function () { log('CONSOLE.ERROR: ' + Array.prototype.join.call(arguments, ' ').slice(0, 3000)); ce.apply(console, arguments); };
  var cw = console.warn;
  console.warn = function () { log('WARN: ' + Array.prototype.join.call(arguments, ' ').slice(0, 800)); cw.apply(console, arguments); };
  var raf = window.requestAnimationFrame.bind(window);
  var calls = 0;
  window.__frames = function () { return calls; };
  window.requestAnimationFrame = function (cb) {
    return raf(function (ts) {
      calls++;
      if (T !== null && calls === 2) {
        var s = document.getElementById('scrubber');
        s.value = String(T);
        s.dispatchEvent(new Event('input'));
      }
      cb(ts);
    });
  };
  window.addEventListener('load', function () { log('LOADED; THREE=' + (typeof THREE !== 'undefined' ? THREE.REVISION : 'missing')); });
})();
</script>
EOF
