// Declarations are split per program so no vertex varying is left unread by its fragment shader.
const VERT_PARS_GLASS = [
  'attribute float aS;',
  'varying float vS;'
].join('\n');
const FRAG_PARS_GLASS = [
  'uniform float uSimTime;',
  'uniform float uFront;',
  'uniform float uFlash;',
  'uniform float uCutS;',
  'varying float vS;',
  'vec3 isoChrom(float gam) { vec3 sn = sin(3.14159265 * gam / vec3(650.0, 550.0, 460.0)); return sn * sn; }'
].join('\n');
const VERT_PARS_FRACTURE = [
  'attribute float aS;',
  'varying float vS;',
  'varying vec3 vObjPos;',
  'uniform float uSimTime;',
  'uniform float uFracT0;',
  'uniform float uFracDur;'
].join('\n');
const FRAG_PARS_FRACTURE = [
  'uniform float uSimTime;',
  'uniform float uFront;',
  'varying float vS;',
  'varying vec3 vObjPos;',
  'float h31(vec3 p) { return fract(sin(dot(p, vec3(127.1, 311.7, 74.7))) * 43758.5453123); }'
].join('\n');
const VERT_BEGIN_GLASS = [
  'vec3 transformed = vec3(position);',
  'vS = aS;'
].join('\n');

