// Triboluminescent flash: ignites at the cut, decays over ~0.2 s.
const flashAt = (t) => {
  const tt = t - T_SNIP;
  return tt < 0 ? 0 : Math.exp(-tt / 0.18) * (1 - Math.exp(-tt / 0.025));
};
// Fracture nucleation glow at the cut face: builds through 3.8-4.4 s, fades as the front takes over.
const nucAt = (t) => sstep(T_SNIP + 0.05, T_FRONT0, t) * (1 - sstep(T_FRONT0 + 0.1, T_FRONT0 + 0.5, t));

function renderAt(tIn) {
  const t = clamp(tIn, 0, DURATION);
  U.uSimTime.value = t;
  U.uFront.value = frontAt(t);
  U.uFlash.value = flashAt(t);
  U.uNuc.value = nucAt(t);

