// Dark anodised clamp on the neck, with an arm and a suspension wire leaving the frame.
const clampGroup = new THREE.Group();
const P_CL = spineP(I_CLAMP);
const T_CL = [SP_T[3 * I_CLAMP], SP_T[3 * I_CLAMP + 1], SP_T[3 * I_CLAMP + 2]];
const collar = new THREE.Mesh(new THREE.TorusGeometry(0.15, 0.032, 14, 36), anodizedMat);
collar.position.set(P_CL[0], P_CL[1], P_CL[2]);
collar.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), new THREE.Vector3(T_CL[0], T_CL[1], T_CL[2]));
const arm = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.045, 2.6, 14).rotateZ(Math.PI / 2), anodizedMat);
arm.position.set(P_CL[0] - 1.3, P_CL[1], P_CL[2]);
const block = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.34, 0.34), anodizedMat);
block.position.set(P_CL[0] - 2.6, P_CL[1], P_CL[2]);
const wire = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 9, 6), anodizedMat);
wire.position.set(P_CL[0] - 2.6, P_CL[1] + 4.5, P_CL[2]);
clampGroup.add(collar, arm, block, wire);
dropGroup.add(clampGroup);

/* ---------- pre-seeded particle systems (all randomness drawn here, once) ---------- */
const spallP = new Float64Array(3 * SPALL_N), spallV = new Float64Array(3 * SPALL_N), spallS = new Float64Array(SPALL_N);
const nedP = new Float64Array(3 * NEEDLE_N), nedV = new Float64Array(3 * NEEDLE_N), nedAx = new Float64Array(3 * NEEDLE_N);
const nedW = new Float64Array(NEEDLE_N), nedL = new Float64Array(NEEDLE_N), nedR = new Float64Array(NEEDLE_N);
const dustBase = new Float64Array(3 * DUST_N), dustV = new Float64Array(3 * DUST_N);
const shB = new Float64Array(3 * SHARD_N), shD = new Float64Array(3 * SHARD_N);
const shS = new Float64Array(SHARD_N), shT = new Float64Array(SHARD_N), shQ = new Float64Array(4 * SHARD_N);

const spineSample = () => Math.round(rnd() * U_CUT / DU);
function radialDir(idx, out, oi) {                  // random unit direction in the cross-section
  const a = TAU * rnd(), c = Math.cos(a), s = Math.sin(a), o = 3 * idx;
  out[oi] = c * SP_N[o] + s * SP_B[o];
  out[oi + 1] = c * SP_N[o + 1] + s * SP_B[o + 1];
  out[oi + 2] = c * SP_N[o + 2] + s * SP_B[o + 2];
}

function buildParticles() {
  resetRng();
  const d = [0, 0, 0];
  // Lead spall: flung from the impact point, biased away from the bulb (+X).
  for (let i = 0; i < SPALL_N; i++) {
    const r = randUnit();
    const x = Math.abs(r[0]) * 0.85 + 0.15;
    const l = Math.hypot(x, r[1], r[2]);
    const sp = 1.8 + 2.6 * rnd();
    spallP[3 * i] = XHIT + 0.03 * rnd();
    spallP[3 * i + 1] = BULB_R + 0.12 * (rnd() - 0.5);
    spallP[3 * i + 2] = 0.12 * (rnd() - 0.5);
    spallV[3 * i] = x / l * sp;
    spallV[3 * i + 1] = r[1] / l * sp;
    spallV[3 * i + 2] = r[2] / l * sp;
    spallS[i] = 0.55 + 0.9 * rnd();
  }
  // Needles: radial burst from the body.
  for (let i = 0; i < NEEDLE_N; i++) {
    const idx = spineSample(), o = 3 * idx;
    radialDir(idx, d, 0);
    const rho = SP_R[idx] * Math.sqrt(rnd()) * 0.9;
    const sp = 1.4 + 2.6 * rnd(), tw = 0.8 * (rnd() - 0.5);
    for (let a = 0; a < 3; a++) {
      nedP[3 * i + a] = SP_P[o + a] + rho * d[a];
      nedV[3 * i + a] = d[a] * sp + SP_T[o + a] * tw;
    }
    const ax = randUnit();
    nedAx[3 * i] = ax[0]; nedAx[3 * i + 1] = ax[1]; nedAx[3 * i + 2] = ax[2];
    nedW[i] = 2 + 6 * rnd();
    nedL[i] = 0.22 + 0.5 * rnd();
    nedR[i] = 0.8 + 0.6 * rnd();
  }
  // Silica dust: slower radial burst, strong drag, drifts downward.
  for (let i = 0; i < DUST_N; i++) {
    const idx = spineSample(), o = 3 * idx;
    radialDir(idx, d, 0);
    const rho = SP_R[idx] * Math.sqrt(rnd());
    const sp = 0.3 + 1.2 * rnd();
    for (let a = 0; a < 3; a++) {
      dustBase[3 * i + a] = SP_P[o + a] + rho * d[a];
      dustV[3 * i + a] = d[a] * sp;
    }
  }
  // Micro-crystal shards on the surface; each appears when the front passes its s.
  for (let i = 0; i < SHARD_N; i++) {
    const idx = spineSample(), o = 3 * idx;
    radialDir(idx, d, 0);
    for (let a = 0; a < 3; a++) {
      shB[3 * i + a] = SP_P[o + a] + SP_R[idx] * 0.97 * d[a];
      shD[3 * i + a] = d[a];
    }
    shS[i] = 0.55 + 0.9 * rnd();
    shT[i] = T_FRONT0 + (1 - idx * DU / L_TOTAL) * FRONT_DUR;
    const ax = randUnit(), ang = TAU * rnd(), sn = Math.sin(0.5 * ang);
    shQ[4 * i] = ax[0] * sn; shQ[4 * i + 1] = ax[1] * sn; shQ[4 * i + 2] = ax[2] * sn; shQ[4 * i + 3] = Math.cos(0.5 * ang);
  }
}
buildParticles();

const spallMesh = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(0.045, 1), spallMat, SPALL_N);
spallMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
spallMesh.frustumCulled = false;
spallMesh.visible = false;
dropGroup.add(spallMesh);

const needleMesh = new THREE.InstancedMesh(new THREE.CylinderGeometry(0.02, 0.006, 1, 4, 1), needleMat, NEEDLE_N);
needleMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
needleMesh.frustumCulled = false;

