  renderer.compile(scene, camera);
  renderer.render(scene, camera);

  /* =====================================================================
   * 9. Playback state machine and dock wiring
   * ===================================================================== */
  const countdownEl = document.getElementById('countdown');
  const btnRefire = document.getElementById('btn-refire');
  const btnToggle = document.getElementById('btn-toggle');
  const iconPause = document.getElementById('icon-pause');
  const iconPlay = document.getElementById('icon-play');
  const scrubber = document.getElementById('scrubber');
  const speedPills = Array.prototype.slice.call(document.querySelectorAll('.speed-pill'));

  const ST = { COUNTDOWN: 'COUNTDOWN', PLAYING: 'PLAYING', PAUSED: 'PAUSED', REFIRE_HOLD: 'REFIRE_HOLD', ENDED: 'ENDED' };
  let state = ST.PAUSED;            // until the first animation frame starts the countdown
  let started = false;
  let lastTs = 0;
  let simTime = 0;
  let playbackSpeed = 1.0;
  let countdownElapsed = 0;
  let holdElapsed = 0;
  let shownCount = '';

  function showCount(txt) {
    if (shownCount === txt) return;
    shownCount = txt;
    countdownEl.textContent = txt;
    countdownEl.style.display = 'block';
  }
  function hideCountdown() {
    shownCount = '';
    countdownEl.style.display = 'none';
    countdownEl.textContent = '';
  }
  function setPlayIcon(playing) {
    iconPause.style.display = playing ? '' : 'none';
    iconPlay.style.display = playing ? 'none' : '';
    btnToggle.setAttribute('aria-label', playing ? 'Pause' : 'Play');
  }
  function renderNow() {
    renderAt(simTime);
    renderer.render(scene, camera);
  }

  hideCountdown();
  scrubber.value = '0';

  btnToggle.addEventListener('click', function () {
    if (state === ST.PLAYING) {
      state = ST.PAUSED;
      setPlayIcon(false);
    } else if (state === ST.COUNTDOWN || state === ST.REFIRE_HOLD) {
      hideCountdown();
      simTime = 0;
      scrubber.value = '0';
      state = ST.PAUSED;
      setPlayIcon(false);
      renderNow();
    } else if (state === ST.PAUSED) {
      state = ST.PLAYING;
      setPlayIcon(true);
    } else if (state === ST.ENDED) {
      hideCountdown();
      simTime = 0;
      scrubber.value = '0';
      state = ST.PLAYING;
      setPlayIcon(true);
      renderNow();
    }
  });

  btnRefire.addEventListener('click', function () {
    hideCountdown();
    simTime = 0;
    scrubber.value = '0';
    holdElapsed = 0;
    state = ST.REFIRE_HOLD;
    setPlayIcon(true);
    renderNow();
  });

  scrubber.addEventListener('input', function () {
    hideCountdown();
    simTime = clamp(parseFloat(scrubber.value) || 0, 0, DURATION);
    state = ST.PAUSED;
    setPlayIcon(false);
    renderNow();
  });

  speedPills.forEach(function (pill) {
    pill.addEventListener('click', function () {
      playbackSpeed = parseFloat(pill.getAttribute('data-speed')) || 1.0;
      speedPills.forEach(function (p) {
        const on = p === pill;
        p.classList.toggle('is-active', on);
        p.setAttribute('aria-checked', on ? 'true' : 'false');
      });
    });
  });

  window.addEventListener('resize', function () {
    renderer.setSize(window.innerWidth, window.innerHeight, false);
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderNow();
  });

  function frame(ts) {
    requestAnimationFrame(frame);
    let raw = 0;
    if (!started) {
      started = true;
      state = ST.COUNTDOWN;
      countdownElapsed = 0;
      showCount('3');
    } else {
      raw = Math.max(0, (ts - lastTs) / 1000);
    }
    lastTs = ts;
    const dt = Math.min(raw, 0.1);

    if (state === ST.COUNTDOWN) {
      countdownElapsed += dt;
      if (countdownElapsed >= 3) {
        hideCountdown();
        state = ST.PLAYING;
        setPlayIcon(true);
      } else {
        showCount(countdownElapsed < 1 ? '3' : countdownElapsed < 2 ? '2' : '1');
      }
    } else if (state === ST.REFIRE_HOLD) {
      holdElapsed += dt;
      if (holdElapsed >= 1) state = ST.PLAYING;
    } else if (state === ST.PLAYING) {
      simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
      if (simTime >= DURATION) {
        simTime = DURATION;
        state = ST.ENDED;
        setPlayIcon(false);
      }
      scrubber.value = simTime.toFixed(3);
    }
    renderNow();
  }
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
